    expect(ultimaChamada().opcoes.method).toBe('PUT');
  });

  /**
   * @caso CT-UNI-339
   * @nivel unitario
   * @atributo compatibilidade
   * @subatributo interoperabilidade
   * @requisito RN21
   * @objetivo Repassar PATCH para ativar ou desativar usuários
