// Integração do auto-cadastro de paciente: formulário, registro, login automático e erros (RF01, RN01–RN03, RN06).
import { describe, test, expect, beforeEach, afterEach, vi } from 'vitest';
import { render, screen, cleanup, waitFor, fireEvent } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { MemoryRouter, Route, Routes } from 'react-router-dom';

vi.mock('../../src/api', () => ({
  authApi: { login: vi.fn(), registrar: vi.fn(), me: vi.fn() },
  especialidadesApi: { listar: vi.fn(), criar: vi.fn() },
  medicosApi: { listar: vi.fn(), criar: vi.fn(), horarios: vi.fn(), grade: vi.fn(), salvarGrade: vi.fn(), bloqueios: vi.fn(), criarBloqueio: vi.fn(), removerBloqueio: vi.fn() },
  pacientesApi: { listar: vi.fn(), criar: vi.fn() },
  consultasApi: { listar: vi.fn(), agendar: vi.fn(), confirmar: vi.fn(), cancelar: vi.fn(), remarcar: vi.fn(), realizar: vi.fn(), falta: vi.fn() },
  adminApi: { definirAtivo: vi.fn(), resumo: vi.fn() },
}));

import { authApi } from '../../src/api';
import { AuthProvider } from '../../src/contexts/AuthContext';
import { ToastProvider } from '../../src/contexts/ToastContext';
import { CadastroPage } from '../../src/pages/CadastroPage';

const PACIENTE = { id: 9, nome: 'Ana Pereira', perfil: 'PACIENTE' };

function montarCadastro() {
  return render(
    <MemoryRouter initialEntries={['/cadastro']}>
      <AuthProvider>
        <ToastProvider>
          <Routes>
            <Route path="/cadastro" element={<CadastroPage />} />
            <Route path="/paciente" element={<div>Tela inicial do paciente</div>} />
            <Route path="/login" element={<div>Tela de login</div>} />
          </Routes>
        </ToastProvider>
      </AuthProvider>
    </MemoryRouter>,
  );
}

async function preencher(usuario, dados = {}) {
  await usuario.type(screen.getByLabelText(/Nome completo/), dados.nome ?? 'Ana Pereira');
  await usuario.type(screen.getByLabelText(/E-mail/), dados.email ?? 'ana@email.com');
  await usuario.type(screen.getByLabelText(/Senha/), dados.senha ?? 'Senha123');
  await usuario.type(screen.getByLabelText(/^CPF/), dados.cpf ?? '52998224725');
  fireEvent.change(screen.getByLabelText(/Data de nascimento/), { target: { value: dados.dataNascimento ?? '1990-05-14' } });
  if (dados.telefone) await usuario.type(screen.getByLabelText(/Telefone/), dados.telefone);
}

beforeEach(() => {
  vi.clearAllMocks();
  localStorage.clear();
  authApi.registrar.mockResolvedValue({ id: 9, nome: 'Ana Pereira' });
  authApi.login.mockResolvedValue({ token: 'jwt-ana', usuario: PACIENTE });
});

afterEach(cleanup);

describe('CadastroPage — formulário', () => {
  /**
   * @caso CT-INT-321
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF02.1, RF02.3
   * @objetivo Coletar todos os dados necessários para o cadastro
   * @resultadoEsperado Nome, e-mail, senha, CPF, nascimento, telefone e responsável estão presentes
   */
  test('renders every patient field', () => {
    montarCadastro();
    expect(screen.getByLabelText(/Nome completo/)).toBeInTheDocument();
    expect(screen.getByLabelText(/E-mail/)).toBeInTheDocument();
    expect(screen.getByLabelText(/Senha/)).toBeInTheDocument();
    expect(screen.getByLabelText(/^CPF/)).toBeInTheDocument();
    expect(screen.getByLabelText(/Data de nascimento/)).toBeInTheDocument();
    expect(screen.getByLabelText(/Telefone/)).toBeInTheDocument();
    expect(screen.getByLabelText(/Nome do responsável/)).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-322
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF06
   * @objetivo Distinguir campos obrigatórios dos opcionais
   * @resultadoEsperado Cinco campos exibem o asterisco de obrigatório
   */
  test('marks the five required fields', () => {
    const { container } = montarCadastro();
    expect(container.querySelectorAll('label span[aria-hidden="true"]')).toHaveLength(5);
  });

  /**
   * @caso CT-INT-323
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RN02, RNF06
   * @objetivo Explicar a regra de senha antes do envio
   * @resultadoEsperado O campo de senha mostra a ajuda com o mínimo de caracteres
   */
  test('explains the password rule', () => {
    montarCadastro();
    expect(screen.getByText('Mínimo de 8 caracteres, com letras e números.')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-324
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RN03, RNF06
   * @objetivo Facilitar a digitação do CPF em dispositivos móveis
   * @resultadoEsperado O campo de CPF declara inputMode numérico
   */
  test('uses numeric keyboard hint for CPF', () => {
    montarCadastro();
    expect(screen.getByLabelText(/^CPF/)).toHaveAttribute('inputmode', 'numeric');
  });

  /**
   * @caso CT-INT-325
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Usar seletores de data nativos para a data de nascimento
   * @resultadoEsperado O campo de nascimento é type date
   */
  test('uses a date input for birth date', () => {
    montarCadastro();
    expect(screen.getByLabelText(/Data de nascimento/)).toHaveAttribute('type', 'date');
  });

  /**
   * @caso CT-INT-326
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo operabilidade
   * @requisito RF01.1
   * @objetivo Oferecer o caminho de volta para quem já tem conta
   * @resultadoEsperado O link "Entrar" leva para a tela de login
   */
  test('links back to login', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await usuario.click(screen.getByRole('link', { name: 'Entrar' }));
    expect(screen.getByText('Tela de login')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-327
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo acessibilidade
   * @requisito RNF06
   * @objetivo Identificar a página de cadastro no título da aba
   * @resultadoEsperado document.title é "Criar conta · Clínica+"
   */
  test('sets the signup document title', () => {
    montarCadastro();
    expect(document.title).toBe('Criar conta · Clínica+');
  });

  /**
   * @caso CT-INT-328
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF06
   * @objetivo Explicar o papel do responsável para pacientes menores
   * @resultadoEsperado O campo de responsável traz a ajuda de menor de 18 anos
   */
  test('explains the guardian requirement', () => {
    montarCadastro();
    expect(screen.getByText('Obrigatório para menores de 18 anos.')).toBeInTheDocument();
  });
});

describe('CadastroPage — envio', () => {
  /**
   * @caso CT-INT-329
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF02.1, RN03
   * @objetivo Enviar ao registro os dados digitados no formulário
   * @resultadoEsperado authApi.registrar recebe nome, e-mail, senha, CPF e nascimento
   */
  test('sends the typed patient data', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(authApi.registrar).toHaveBeenCalledWith(expect.objectContaining({
      nome: 'Ana Pereira',
      email: 'ana@email.com',
      senha: 'Senha123',
      cpf: '52998224725',
      dataNascimento: '1990-05-14',
    }));
  });

  /**
   * @caso CT-INT-330
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF02.1, RF01.1
   * @objetivo Entrar automaticamente logo após o cadastro
   * @resultadoEsperado authApi.login é chamado com o e-mail e a senha cadastrados
   */
  test('logs in automatically after registration', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    await waitFor(() => expect(authApi.login).toHaveBeenCalledWith('ana@email.com', 'Senha123'));
  });

  /**
   * @caso CT-INT-331
   * @nivel integracao
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF02.1
   * @objetivo Levar o novo paciente direto para a área de consultas
   * @resultadoEsperado A tela inicial do paciente é exibida
   */
  test('navigates to the patient area after signup', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(await screen.findByText('Tela inicial do paciente')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-332
   * @nivel integracao
   * @atributo seguranca
   * @subatributo autenticidade
   * @requisito RN30
   * @objetivo Manter a sessão do paciente recém-cadastrado
   * @resultadoEsperado O token é gravado no localStorage
   */
  test('stores the new session token', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    await waitFor(() => expect(localStorage.getItem('clinica.token')).toBe('jwt-ana'));
  });

  /**
   * @caso CT-INT-333
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF06
   * @objetivo Confirmar o cadastro com um aviso claro
   * @resultadoEsperado Um toast "Cadastro concluído" aparece
   */
  test('shows the signup success toast', async () => {
    const usuario = userEvent.setup();
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(await screen.findByText('Cadastro concluído')).toBeInTheDocument();
  });

  /**
   * @caso CT-INT-334
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Explicar por que o cadastro foi recusado
   * @resultadoEsperado A mensagem da API aparece em um alerta inline
   */
  test('shows the registration error inline', async () => {
    const usuario = userEvent.setup();
    authApi.registrar.mockRejectedValue(new Error('E-mail já cadastrado.'));
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('E-mail já cadastrado.');
  });

  /**
   * @caso CT-INT-335
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RF02.1
   * @objetivo Não tentar autenticar quando o cadastro falhou
   * @resultadoEsperado authApi.login não é chamado após rejeição do registro
   */
  test('does not log in when registration fails', async () => {
    const usuario = userEvent.setup();
    authApi.registrar.mockRejectedValue(new Error('CPF inválido.'));
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    await screen.findByRole('alert');
    expect(authApi.login).not.toHaveBeenCalled();
  });

  /**
   * @caso CT-INT-336
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo capacidade-de-recuperacao
   * @requisito RNF04
   * @objetivo Preservar os dados digitados para corrigir apenas o campo inválido
   * @resultadoEsperado Após erro, o e-mail digitado continua no campo
   */
  test('keeps typed data after a failure', async () => {
    const usuario = userEvent.setup();
    authApi.registrar.mockRejectedValue(new Error('CPF inválido.'));
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    await screen.findByRole('alert');
    expect(screen.getByLabelText(/E-mail/)).toHaveValue('ana@email.com');
  });

  /**
   * @caso CT-INT-337
   * @nivel integracao
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RF02.1, RNF04
   * @objetivo Informar quando o cadastro deu certo mas o login automático falhou
   * @resultadoEsperado O erro do login é exibido em alerta
   */
  test('shows an error when automatic login fails', async () => {
    const usuario = userEvent.setup();
    authApi.login.mockRejectedValue(new Error('Não foi possível conectar ao servidor.'));
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(await screen.findByRole('alert')).toHaveTextContent('Não foi possível conectar ao servidor.');
  });

  /**
   * @caso CT-INT-338
   * @nivel integracao
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF06
   * @objetivo Indicar progresso durante o cadastro
   * @resultadoEsperado O botão exibe "Cadastrando..." e fica desabilitado
   */
  test('shows progress while registering', async () => {
    const usuario = userEvent.setup();
    authApi.registrar.mockReturnValue(new Promise(() => {}));
    montarCadastro();
    await preencher(usuario);
    await usuario.click(screen.getByRole('button', { name: 'Criar conta' }));
    expect(await screen.findByRole('button', { name: 'Cadastrando...' })).toBeDisabled();
  });
});

frontend/__testes__/unitario/formatadore.source:
// Formatadores puros usados por toda a interface (RF09, RN23, RNF06).
import { describe, test, expect, afterEach, vi } from 'vitest';
import {
  formatarMoeda,
  formatarDataHora,
  hojeISO,
  NOMES_DIAS,
  STATUS_CONSULTA,
  estaAtiva,
} from '../../src/utils/formatadores';

// O Intl separa "R$" do valor com espaço não separável; normalizamos só para comparar.
const brl = (texto) => texto.replace(/\u00a0/g, ' ');

describe('formatarMoeda', () => {
  /**
   * @caso CT-UNI-301
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN22, RNF06
   * @objetivo Converter centavos inteiros em moeda brasileira
   * @resultadoEsperado 15000 centavos viram "R$ 150,00"
   */
  test('formata valores em reais a partir de centavos', () => {
    expect(brl(formatarMoeda(15000))).toBe('R$ 150,00');
  });

  /**
   * @caso CT-UNI-302
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF08.2, RN24
   * @objetivo Representar o retorno gratuito sem casas decimais indevidas
   * @resultadoEsperado 0 centavos vira "R$ 0,00"
   */
  test('formata o valor zero', () => {
    expect(brl(formatarMoeda(0))).toBe('R$ 0,00');
  });

  /**
   * @caso CT-UNI-303
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RN23
   * @objetivo Formatar o preço com desconto de idoso da Clínica Geral
   * @resultadoEsperado 13500 centavos viram "R$ 135,00"
   */
  test('formata o valor com desconto de idoso', () => {
    expect(brl(formatarMoeda(13500))).toBe('R$ 135,00');
  });

  /**
   * @caso CT-UNI-304
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF03.1, RN22
   * @objetivo Formatar o preço base da Cardiologia
   * @resultadoEsperado 30000 centavos viram "R$ 300,00"
   */
  test('formata o preço da Cardiologia', () => {
    expect(brl(formatarMoeda(30000))).toBe('R$ 300,00');
  });

  /**
   * @caso CT-UNI-305
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF06
   * @objetivo Usar separador de milhar e vírgula decimal do padrão brasileiro
   * @resultadoEsperado 123456 centavos viram "R$ 1.234,56"
   */
  test('usa milhar com ponto e decimal com vírgula', () => {
    expect(brl(formatarMoeda(123456))).toBe('R$ 1.234,56');
  });

  /**
   * @caso CT-UNI-306
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Formatar centavos com apenas um dígito de centavo
   * @resultadoEsperado 199 centavos viram "R$ 1,99"
   */
  test('preserva centavos menores que dez', () => {
    expect(brl(formatarMoeda(199))).toBe('R$ 1,99');
  });

  /**
   * @caso CT-UNI-307
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Exibir o sinal negativo em estornos ou ajustes
   * @resultadoEsperado -1000 centavos viram "-R$ 10,00"
   */
  test('formata valores negativos', () => {
    expect(brl(formatarMoeda(-1000))).toBe('-R$ 10,00');
  });

  /**
   * @caso CT-UNI-308
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RF11.1, RNF05
   * @objetivo Suportar faturamento alto no relatório sem perder legibilidade
   * @resultadoEsperado 100000000 centavos viram "R$ 1.000.000,00"
   */
  test('formata faturamento de sete dígitos', () => {
    expect(brl(formatarMoeda(100000000))).toBe('R$ 1.000.000,00');
  });
});

describe('formatarDataHora', () => {
  /**
   * @caso CT-UNI-309
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter data ISO em data brasileira
   * @resultadoEsperado "2026-10-19" vira "19/10/2026"
   */
  test('converte data ISO para o padrão brasileiro', () => {
    expect(formatarDataHora('2026-10-19')).toBe('19/10/2026');
  });

  /**
   * @caso CT-UNI-310
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Converter data e hora ISO em data e hora brasileiras
   * @resultadoEsperado "2026-10-19 08:00" vira "19/10/2026 08:00"
   */
  test('converte data e hora ISO', () => {
    expect(formatarDataHora('2026-10-19 08:00')).toBe('19/10/2026 08:00');
  });

  /**
   * @caso CT-UNI-311
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Não quebrar ao renderizar um campo sem valor
   * @resultadoEsperado String vazia é devolvida para entrada vazia
   */
  test('devolve string vazia para entrada vazia', () => {
    expect(formatarDataHora('')).toBe('');
  });

  /**
   * @caso CT-UNI-312
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Tratar campos opcionais nulos como ausentes
   * @resultadoEsperado null e undefined devolvem string vazia
   */
  test('devolve string vazia para null e undefined', () => {
    expect(formatarDataHora(null)).toBe('');
    expect(formatarDataHora(undefined)).toBe('');
  });

  /**
   * @caso CT-UNI-313
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF02.3, RNF06
   * @objetivo Formatar a data de nascimento de um paciente adulto
   * @resultadoEsperado "1990-05-14" vira "14/05/1990"
   */
  test('formata data de nascimento', () => {
    expect(formatarDataHora('1990-05-14')).toBe('14/05/1990');
  });

  /**
   * @caso CT-UNI-314
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Manter horários no fim do dia sem conversão de fuso
   * @resultadoEsperado "2026-01-05 23:59" vira "05/01/2026 23:59"
   */
  test('preserva horário no fim do dia', () => {
    expect(formatarDataHora('2026-01-05 23:59')).toBe('05/01/2026 23:59');
  });

  /**
   * @caso CT-UNI-315
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF06
   * @objetivo Formatar ano bissexto sem deslocar o dia
   * @resultadoEsperado "2028-02-29" vira "29/02/2028"
   */
  test('formata 29 de fevereiro', () => {
    expect(formatarDataHora('2028-02-29')).toBe('29/02/2028');
  });

  /**
   * @caso CT-UNI-316
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF06
   * @objetivo Formatar o último dia do ano com meia-noite
   * @resultadoEsperado "2026-12-31 00:00" vira "31/12/2026 00:00"
   */
  test('formata virada de ano à meia-noite', () => {
    expect(formatarDataHora('2026-12-31 00:00')).toBe('31/12/2026 00:00');
  });
});

describe('hojeISO', () => {
  afterEach(() => {
    vi.useRealTimers();
  });

  /**
   * @caso CT-UNI-317
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RNF07
   * @objetivo Devolver a data local no formato usado pela API
   * @resultadoEsperado Retorna uma string no padrão AAAA-MM-DD
   */
  test('devolve data no formato AAAA-MM-DD', () => {
    expect(hojeISO()).toMatch(/^\d{4}-\d{2}-\d{2}$/);
  });

  /**
   * @caso CT-UNI-318
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF10.2, RNF06
   * @objetivo Preencher o filtro de data da agenda do médico com o dia atual
   * @resultadoEsperado Com o relógio em 19/10/2026 devolve "2026-10-19"
   */
  test('usa o dia corrente do relógio local', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(2026, 9, 19, 8, 0, 0));
    expect(hojeISO()).toBe('2026-10-19');
  });

  /**
   * @caso CT-UNI-319
   * @nivel unitario
   * @atributo usabilidade
   * @subatributo inteligibilidade
   * @requisito RNF07
   * @objetivo Não perder o zero à esquerda em meses e dias menores que dez
   * @resultadoEsperado Em 05/01/2026 devolve "2026-01-05"
   */
  test('preenche mês e dia com zero à esquerda', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(2026, 0, 5, 12, 0, 0));
    expect(hojeISO()).toBe('2026-01-05');
  });

  /**
   * @caso CT-UNI-320
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo maturidade
   * @requisito RNF07
   * @objetivo Manter o ano correto no último dia do ano
   * @resultadoEsperado Em 31/12/2026 devolve "2026-12-31"
   */
  test('devolve o ano corrente na virada do ano', () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(2026, 11, 31, 23, 30, 0));
    expect(hojeISO()).toBe('2026-12-31');
  });
});

describe('NOMES_DIAS', () => {
  /**
   * @caso CT-UNI-321
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF05.1, RN10
   * @objetivo Oferecer os sete dias usados na grade semanal
   * @resultadoEsperado O array tem exatamente sete posições
   */
  test('lista os sete dias da semana', () => {
    expect(NOMES_DIAS).toHaveLength(7);
  });

  /**
   * @caso CT-UNI-322
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF05.1, RN10
   * @objetivo Alinhar o índice do array ao retorno de Date.getDay
   * @resultadoEsperado Índice 0 é Domingo e índice 6 é Sábado
   */
  test('começa no domingo e termina no sábado', () => {
    expect(NOMES_DIAS[0]).toBe('Domingo');
    expect(NOMES_DIAS[6]).toBe('Sábado');
  });

  /**
   * @caso CT-UNI-323
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF05.1, RN10
   * @objetivo Nomear a segunda-feira, dia da semana fixado nos testes
   * @resultadoEsperado Índice 1 corresponde a "Segunda"
   */
  test('nomeia a segunda-feira no índice 1', () => {
    const segunda = new Date(2026, 9, 19);
    expect(NOMES_DIAS[segunda.getDay()]).toBe('Segunda');
  });
});

describe('STATUS_CONSULTA', () => {
  /**
   * @caso CT-UNI-324
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo completude
   * @requisito RF09
   * @objetivo Expor todos os estados da máquina de consultas nos filtros
   * @resultadoEsperado O array contém os cinco status na ordem de exibição
   */
  test('lista os cinco status na ordem esperada', () => {
    expect(STATUS_CONSULTA).toEqual(['AGENDADA', 'CONFIRMADA', 'REALIZADA', 'FALTA', 'CANCELADA']);
  });

  /**
   * @caso CT-UNI-325
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.2
   * @objetivo Garantir que o status final CANCELADA não some da lista de filtros
   * @resultadoEsperado O array inclui CANCELADA
   */
  test('inclui o status final CANCELADA', () => {
    expect(STATUS_CONSULTA).toContain('CANCELADA');
  });
});

describe('estaAtiva', () => {
  /**
   * @caso CT-UNI-326
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09, RN25
   * @objetivo Considerar AGENDADA como consulta que ainda aceita ações
   * @resultadoEsperado estaAtiva devolve true
   */
  test('considera AGENDADA ativa', () => {
    expect(estaAtiva({ status: 'AGENDADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-327
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.2, RF09.3, RN26, RN27
   * @objetivo Considerar CONFIRMADA como consulta que ainda aceita cancelamento e remarcação
   * @resultadoEsperado estaAtiva devolve true
   */
  test('considera CONFIRMADA ativa', () => {
    expect(estaAtiva({ status: 'CONFIRMADA' })).toBe(true);
  });

  /**
   * @caso CT-UNI-328
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.4
   * @objetivo Não oferecer ações para consultas já realizadas
   * @resultadoEsperado estaAtiva devolve false para REALIZADA
   */
  test('considera REALIZADA inativa', () => {
    expect(estaAtiva({ status: 'REALIZADA' })).toBe(false);
  });

  /**
   * @caso CT-UNI-329
   * @nivel unitario
   * @atributo adequacao-funcional
   * @subatributo correcao
   * @requisito RF09.5, RN29
   * @objetivo Não oferecer ações para consultas com falta registrada
   * @resultadoEsperado estaAtiva devolve false para FALTA
   */
  test('considera FALTA inativa', () => {
    expect(estaAtiva({ status: 'FALTA' })).toBe(false);
  });

  /**
   * @caso CT-UNI-330
   * @nivel unitario
   * @atributo confiabilidade
   * @subatributo tolerancia-a-falhas
   * @requisito RNF04
   * @objetivo Tratar status desconhecido como inativo em vez de lançar erro
   * @resultadoEsperado estaAtiva devolve false para CANCELADA e para valor arbitrário
   */
  test('considera CANCELADA e status desconhecido inativos', () => {
    expect(estaAtiva({ status: 'CANCELADA' })).toBe(false);
    expect(estaAtiva({ status: 'INEXISTENTE' })).toBe(false);
  });
});

